SELECT * FROM conversation
WHERE (user1_type = #{user1Type} AND user1_id = #{user1Id}
   AND user2_type = #{user2Type} AND user2_id = #{user2Id})
   OR (user1_type = #{user2Type} AND user1_id = #{user2Id}
   AND user2_type = #{user1Type} AND user2_id = #{user1Id})
LIMIT 1

